script:
// Better Journal: журнал полётов. Запуски, посадки, аварии, смена мира. Хранится только в localStorage у игрока.
// Клавиша F8 открывает журнал: там можно экспортировать записи в JSON или очистить их.
(function () {
  var KEY = 'bjournal_v1', MAX = 500, prevLanded = null, lastBody = null, flightMax = 0, flightStart = 0, tickAcc = 0;

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function load() { try { var a = JSON.parse(localStorage.getItem(KEY) || '[]'); return Array.isArray(a) ? a : []; } catch (e) { return []; } }
  function save(a) { try { localStorage.setItem(KEY, JSON.stringify(a.slice(-MAX))); } catch (e) { game.showWarn('Журнал: не удалось сохранить запись'); } }
  function add(type, text, extra) {
    var a = load(); a.push(Object.assign({ t: new Date().toISOString(), type: type, text: text }, extra || {})); save(a);
  }
  function bodyName(st) { var b = game.BODIES && game.BODIES[st.body]; return (b && b.name) || st.body || '—'; }
  function fmtAlt(m) { return m >= 1000 ? (m / 1000).toFixed(1) + ' км' : Math.round(m) + ' м'; }

  game.on('world', function () { var st = game.state(); add('мир', 'Мир загружен: ' + bodyName(st)); lastBody = st.body; });
  game.on('launch', function () {
    var st = game.state(); flightStart = Date.now(); flightMax = 0;
    add('запуск', 'Запуск с ' + bodyName(st), { body: st.body });
  });
  game.on('crash', function () {
    var st = game.state();
    add('авария', 'Авария у ' + bodyName(st) + ', макс. высота ' + fmtAlt(flightMax), { body: st.body, maxAlt: Math.round(flightMax) });
  });
  game.on('tick', function (dt) {
    tickAcc += dt || 0; if (tickAcc < 0.5) return; tickAcc = 0;
    var st = game.state(); if (st.mode !== 'FLIGHT') return;
    if (st.altitude > flightMax) flightMax = st.altitude;
    if (lastBody !== null && st.body !== lastBody) { add('мир', 'Смена сферы влияния: ' + bodyName(st), { body: st.body }); lastBody = st.body; }
    if (prevLanded === false && st.landed) {
      add('посадка', 'Посадка на ' + bodyName(st) + ' (макс. высота ' + fmtAlt(flightMax) + ')', { body: st.body, maxAlt: Math.round(flightMax) });
    }
    prevLanded = !!st.landed;
  });

  function openJournal() {
    var old = document.getElementById('bjOv'); if (old) { old.remove(); return; }
    var a = load().slice().reverse();
    var rows = a.length ? a.map(function (e) {
      var d = new Date(e.t); var when = d.toLocaleString('ru-RU', { dateStyle: 'short', timeStyle: 'short' });
      return '<div style="padding:5px 0;border-bottom:1px solid #2a3550;font-size:13px"><span style="color:#8fa0c0">' + esc(when) + '</span> · <b>' + esc(e.type) + '</b><br>' + esc(e.text) + '</div>';
    }).join('') : '<div style="color:#8fa0c0">Записей пока нет. Запустите ракету.</div>';
    var ov = document.createElement('div'); ov.id = 'bjOv';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center';
    ov.innerHTML = '<div class="box panel" style="max-width:600px;width:92%;max-height:80vh;overflow:auto;padding:14px">' +
      '<button class="close-x" id="bjClose">✖</button><h3>📓 Журнал полётов (' + a.length + ')</h3>' +
      '<div style="display:flex;gap:6px;margin-bottom:8px"><button class="btn" id="bjExp">⬇️ Экспорт JSON</button><button class="btn" id="bjClr">🗑 Очистить</button></div>' +
      '<div>' + rows + '</div></div>';
    document.body.appendChild(ov);
    document.getElementById('bjClose').onclick = function () { ov.remove(); };
    document.getElementById('bjExp').onclick = function () {
      var blob = new Blob([JSON.stringify(load(), null, 2)], { type: 'application/json' });
      var link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'alt-space-journal.json';
      document.body.appendChild(link); link.click(); setTimeout(function () { URL.revokeObjectURL(link.href); link.remove(); }, 800);
    };
    document.getElementById('bjClr').onclick = function () { if (confirm('Очистить журнал полётов?')) { save([]); ov.remove(); game.notify('📓 Журнал очищен'); } };
  }

  window.addEventListener('keydown', function (e) {
    if (e.code !== 'F8' || e.repeat) return;
    var t = e.target; if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT')) return;
    e.preventDefault(); openJournal();
  });
})();
